Assuming React + `fetch`:

```jsx
import { useState, useEffect } from "react";

function useDebounce(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

export function Search() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const debounced = useDebounce(query, 300);

  useEffect(() => {
    if (!debounced.trim()) return setResults([]);
    const ctrl = new AbortController();
    fetch(`/api/search?q=${encodeURIComponent(debounced)}`, { signal: ctrl.signal })
      .then((r) => r.json())
      .then(setResults)
      .catch((e) => e.name !== "AbortError" && console.error(e));
    return () => ctrl.abort();
  }, [debounced]);

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <ul>{results.map((r) => <li key={r.id}>{r.name}</li>)}</ul>
    </>
  );
}
```

Input stays responsive (`query` updates per keystroke); only `debounced` triggers the fetch. `AbortController` cancels in-flight requests so a slow old response can't overwrite a newer one.

